"""Immutable native PostgreSQL baseline for Work persistence."""

from cli_agent_orchestrator.clients.postgres.migrations import ComponentMigration

# These seven initially-immediate FKs are exactly the intra-SCC edges in the
# Work relation graph. Bulk migration may defer only those constraints while
# copying verified data; regular Work writes stay immediate.
