    "CREATE TABLE work_attempt_credentials (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(TRUE AND generation>0),\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nprincipal_id TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL CHECK(TRUE AND grant_revision>0),\ninstallation_uuid TEXT NOT NULL CHECK(length(installation_uuid)=32\n            AND installation_uuid !~ '[^0-9a-f]'),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64\n            AND contract_hash !~ '[^0-9a-f]'),\nattempt_revision BIGINT NOT NULL CHECK(TRUE AND attempt_revision>0),\nlease_expires_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND lease_expires_at>0),\nexpires_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND expires_at>0),\ncredential_sha256 TEXT NOT NULL UNIQUE CHECK(length(credential_sha256)=64\n            AND credential_sha256 !~ '[^0-9a-f]'),\nissued_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND issued_at>0),\nschema_version BIGINT NOT NULL DEFAULT 1 CHECK(TRUE AND schema_version=1),\nPRIMARY KEY(attempt_id,generation),\nCHECK(expires_at<=lease_expires_at))",
