    "CREATE TABLE work_bubblewrap_release_claims (attempt_id TEXT PRIMARY KEY,\ngeneration BIGINT NOT NULL CHECK(TRUE AND generation>0),\nschema_version BIGINT NOT NULL DEFAULT 1 CHECK(TRUE AND schema_version=1),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64 AND contract_hash !~ '[^0-9a-f]'),\ncommand_token TEXT NOT NULL,\nexecutable_sha256 TEXT NOT NULL\n            CHECK(length(executable_sha256)=64 AND executable_sha256 !~ '[^0-9a-f]'),\nack_sha256 TEXT NOT NULL CHECK(length(ack_sha256)=64 AND ack_sha256 !~ '[^0-9a-f]'),\nprocess_identity_sha256 TEXT NOT NULL\n            CHECK(length(process_identity_sha256)=64 AND process_identity_sha256 !~ '[^0-9a-f]'),\nclaimed_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND claimed_at>0))",
