    "CREATE TABLE work_delivery_orders (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\noperation_kind TEXT NOT NULL,\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nadapter_version BIGINT NOT NULL CHECK(adapter_version>0),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64),\npayload_json TEXT NOT NULL CHECK((payload_json IS JSON)\n            AND (CASE WHEN payload_json IS JSON THEN json_typeof(payload_json::json)='object' ELSE FALSE END) AND length(payload_json)<=65536),\nrequest_hash TEXT NOT NULL CHECK(length(request_hash)=64),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64),\nPRIMARY KEY(attempt_id,generation))",
    "CREATE TABLE work_dispatch_bindings (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nprincipal_id TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL CHECK(grant_revision>0),\ncontract_id TEXT NOT NULL,\ncontract_json TEXT NOT NULL CHECK((contract_json IS JSON)\n            AND (CASE WHEN contract_json IS JSON THEN json_typeof(contract_json::json)='object' ELSE FALSE END)\n            AND (CASE WHEN contract_json IS JSON THEN CASE WHEN json_typeof(json_extract_path(contract_json::json,'schema_version'))='number' AND json_extract_path_text(contract_json::json,'schema_version') ~ '^-?[0-9]+$' THEN json_extract_path_text(contract_json::json,'schema_version')::numeric=1 ELSE FALSE END ELSE FALSE END)\n            AND (CASE WHEN contract_json IS JSON THEN json_typeof(json_extract_path(contract_json::json,'id'))='string' ELSE FALSE END)\n            AND coalesce(json_extract_path_text((contract_json)::json,'id'),'')=contract_id\n            AND length(contract_json)<=32768),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64),\nsnapshot_id TEXT NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL,\nPRIMARY KEY(attempt_id,generation))",
    "CREATE TABLE work_dispatch_v2_evidence (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\ncontract_json TEXT NOT NULL CHECK((contract_json IS JSON)\n            AND (CASE WHEN contract_json IS JSON THEN json_typeof(contract_json::json)='object' ELSE FALSE END)\n            AND (CASE WHEN contract_json IS JSON THEN CASE WHEN json_typeof(json_extract_path(contract_json::json,'schema_version'))='number' AND json_extract_path_text(contract_json::json,'schema_version') ~ '^-?[0-9]+$' THEN json_extract_path_text(contract_json::json,'schema_version')::numeric=2 ELSE FALSE END ELSE FALSE END)\n            AND length(contract_json)<=32768),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64\n            AND contract_hash !~ '[^0-9a-f]'),\nPRIMARY KEY(attempt_id,generation))",
