    "CREATE TABLE work_lineage_projection_intents (child_attempt_id TEXT NOT NULL,\nchild_generation BIGINT NOT NULL CHECK(child_generation>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nstate TEXT NOT NULL CHECK(state='planned'),\ncreated_at DOUBLE PRECISION NOT NULL,\nPRIMARY KEY(child_attempt_id,child_generation))",
    "CREATE TABLE work_mcp_proxy_effect_events (effect_id TEXT NOT NULL,\nsequence BIGINT NOT NULL CHECK(TRUE AND sequence>0),\nstate TEXT NOT NULL CHECK(state IN\n            ('intent','completed','failed_before_effect','uncertain','reconciled')),\nresponse_sha256 TEXT CHECK(response_sha256 IS NULL OR\n            (length(response_sha256)=64 AND response_sha256 !~ '[^0-9a-f]')),\nresolution_sha256 TEXT CHECK(resolution_sha256 IS NULL OR\n            (length(resolution_sha256)=64 AND resolution_sha256 !~ '[^0-9a-f]')),\noccurred_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND occurred_at>0),\nPRIMARY KEY(effect_id,sequence),\nCHECK((state='completed' AND response_sha256 IS NOT NULL) OR\n              (state!='completed' AND response_sha256 IS NULL)),\nCHECK((state='reconciled' AND resolution_sha256 IS NOT NULL) OR\n              (state!='reconciled' AND resolution_sha256 IS NULL)))",
