    "CREATE TABLE work_offline_cut_rejections (id TEXT PRIMARY KEY CHECK(length(id)=32 AND id !~ '[^0-9a-f]'),\nlease_id TEXT NOT NULL,\nphase TEXT NOT NULL CHECK(phase IN ('before','after','promote','stage')),\nreason TEXT NOT NULL CHECK(reason='capture_rejected'),\ncreated_at DOUBLE PRECISION NOT NULL)",
    "CREATE TABLE work_offline_cuts (id TEXT PRIMARY KEY CHECK(length(id)=32 AND id !~ '[^0-9a-f]'),\nstore_identity TEXT NOT NULL,\noperator_principal_id TEXT NOT NULL,\nowner TEXT NOT NULL CHECK(owner='work'),\nscope TEXT NOT NULL CHECK(scope='registered-work-writers'),\nepoch BIGINT NOT NULL CHECK(epoch>0),\nfence BIGINT NOT NULL CHECK(fence>0),\nexpires_at DOUBLE PRECISION NOT NULL,\nrevision BIGINT NOT NULL CHECK(revision>0),\nstate TEXT NOT NULL CHECK(state IN ('live','revoked','expired','published')),\ncreated_at DOUBLE PRECISION NOT NULL,\nrevoked_at DOUBLE PRECISION,\npublished_path TEXT,\npublished_capture_id TEXT,\npublished_manifest_digest TEXT,\npublished_manifest_size BIGINT,\npublished_at DOUBLE PRECISION,\nCHECK(\n            (state='published'\n                AND published_path IS NOT NULL\n                AND published_capture_id IS NOT NULL\n                AND length(published_capture_id)=32\n                AND published_capture_id !~ '[^0-9a-f]'\n                AND published_manifest_digest IS NOT NULL\n                AND length(published_manifest_digest)=64\n                AND published_manifest_digest !~ '[^0-9a-f]'\n                AND published_manifest_size IS NOT NULL\n                AND published_manifest_size>=0\n                AND published_at IS NOT NULL)\n            OR\n            (state<>'published'\n                AND published_path IS NULL\n                AND published_capture_id IS NULL\n                AND published_manifest_digest IS NULL\n                AND published_manifest_size IS NULL\n                AND published_at IS NULL)\n        ))",
    "CREATE TABLE work_origin_authorizations (subject_id TEXT NOT NULL,\norigin_kind TEXT NOT NULL CHECK(origin_kind IN ('child','workflow','receiver')),\nrevision BIGINT NOT NULL CHECK(revision>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nstate TEXT NOT NULL CHECK(state IN ('active','revoked')),\nissuer_id TEXT NOT NULL,\nsubject_revision BIGINT NOT NULL CHECK(subject_revision>0),\njob_id TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL CHECK(grant_revision>0),\nactions TEXT NOT NULL CHECK((actions IS JSON) AND (CASE WHEN actions IS JSON THEN json_typeof(actions::json)='array' ELSE FALSE END)\n            AND (CASE WHEN actions IS JSON THEN CASE WHEN json_typeof(actions::json)='array' THEN json_array_length(actions::json) BETWEEN 1 AND 7 ELSE FALSE END ELSE FALSE END)),\nexpires_at DOUBLE PRECISION NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL,\nPRIMARY KEY(subject_id,origin_kind,revision))",
    "CREATE TABLE work_origin_subjects (subject_id TEXT NOT NULL,\nrevision BIGINT NOT NULL CHECK(revision>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\norigin_kind TEXT NOT NULL CHECK(origin_kind IN ('child','workflow','receiver')),\nstate TEXT NOT NULL CHECK(state IN ('active','revoked')),\nissuer_id TEXT NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL,\nPRIMARY KEY(subject_id,revision),\nUNIQUE(subject_id,origin_kind,revision))",
    "CREATE TABLE work_path_reservations (reservation_set_id TEXT NOT NULL,\nresource_key TEXT NOT NULL,\ndevice BIGINT,\ninode BIGINT,\nPRIMARY KEY(reservation_set_id,resource_key),\nCHECK((device IS NULL AND inode IS NULL) OR (device IS NOT NULL AND inode IS NOT NULL)))",
    "CREATE TABLE work_principals (id TEXT PRIMARY KEY,\nissuer TEXT NOT NULL,\nsubject TEXT NOT NULL,\nkind TEXT NOT NULL CHECK(kind IN ('jwt','local_operator')),\ncreated_at DOUBLE PRECISION NOT NULL,\nUNIQUE(issuer,subject))",
    "CREATE TABLE work_process_identities (attempt_id TEXT PRIMARY KEY,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nprotocol_version BIGINT NOT NULL CHECK(protocol_version=3),\nidentity_json TEXT NOT NULL,\nidentity_sha256 TEXT NOT NULL CHECK(\n            length(identity_sha256)=64 AND identity_sha256 !~ '[^0-9a-f]'\n        ),\ncreated_at DOUBLE PRECISION NOT NULL)",
    "CREATE TABLE work_recovery_context (singleton BIGINT PRIMARY KEY CHECK(singleton=1),\ncontext_version BIGINT NOT NULL CHECK(context_version=1),\nexecution_state TEXT NOT NULL\n            CHECK(execution_state IN ('normal','blocked_restore')),\ninstallation_uuid TEXT NOT NULL UNIQUE\n            CHECK(length(installation_uuid)=32\n                AND installation_uuid !~ '[^0-9a-f]'),\nsource_installation_uuid TEXT\n            CHECK(source_installation_uuid IS NULL OR\n                (length(source_installation_uuid)=32\n                    AND source_installation_uuid !~ '[^0-9a-f]')),\nbundle_digest TEXT\n            CHECK(bundle_digest IS NULL OR\n                (length(bundle_digest)=64 AND bundle_digest !~ '[^0-9a-f]')),\nrestore_receipt TEXT\n            CHECK(restore_receipt IS NULL OR\n                (length(restore_receipt)=64\n                    AND restore_receipt !~ '[^0-9a-f]')),\ncreated_at DOUBLE PRECISION NOT NULL,\nCHECK(\n            (execution_state='normal'\n                AND source_installation_uuid IS NULL\n                AND bundle_digest IS NULL\n                AND restore_receipt IS NULL)\n            OR\n            (execution_state='blocked_restore'\n                AND source_installation_uuid IS NOT NULL\n                AND bundle_digest IS NOT NULL\n                AND restore_receipt IS NOT NULL\n                AND source_installation_uuid<>installation_uuid)\n        ))",
    "CREATE TABLE work_registered_writers (writer_id TEXT PRIMARY KEY,\nowner TEXT NOT NULL CHECK(owner='work'),\nscope TEXT NOT NULL CHECK(scope='registered-work-writers'),\nstate TEXT NOT NULL CHECK(state IN ('active','released')),\nrevision BIGINT NOT NULL CHECK(revision>0),\nregistered_at DOUBLE PRECISION NOT NULL,\nreleased_at DOUBLE PRECISION)",
    "CREATE TABLE work_reservation_sets (id TEXT PRIMARY KEY,\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nrevision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),\ncheckout_root TEXT NOT NULL,\nstate TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','released')),\nexpires_at DOUBLE PRECISION NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL,\nstop_evidence_ref TEXT,\nreleased_at DOUBLE PRECISION,\nUNIQUE(attempt_id,generation),\nCHECK((state='active' AND stop_evidence_ref IS NULL AND released_at IS NULL) OR\n              (state='released' AND stop_evidence_ref IS NOT NULL AND released_at IS NOT NULL)))",
    "CREATE TABLE work_results (id TEXT PRIMARY KEY,\nattempt_id TEXT NOT NULL,\nschema_version BIGINT NOT NULL DEFAULT 1 CHECK(schema_version=1),\ncontent_hash TEXT NOT NULL,\nimmutable_location TEXT NOT NULL,\nbyte_length BIGINT NOT NULL CHECK(byte_length>=0),\nvalidation_state TEXT NOT NULL CHECK(validation_state IN ('verified','rejected')),\nvalidator_id TEXT NOT NULL,\nvalidation_evidence TEXT NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL)",
    "CREATE TABLE work_scheduler_dependencies (job_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\ndependency_id TEXT NOT NULL,\nPRIMARY KEY(work_item_id,dependency_id),\nCHECK(work_item_id!=dependency_id))",
    "CREATE TABLE work_scheduler_policy (singleton BIGINT PRIMARY KEY CHECK(singleton=1),\nrevision BIGINT NOT NULL CHECK(revision>0),\ncapacity BIGINT NOT NULL CHECK(capacity>0),\nmax_queue BIGINT NOT NULL CHECK(max_queue>0),\naging_seconds BIGINT NOT NULL CHECK(aging_seconds>0),\ndispatch_sequence BIGINT NOT NULL DEFAULT 0 CHECK(dispatch_sequence>=0))",
    "CREATE TABLE work_scheduler_requests (id TEXT PRIMARY KEY,\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nrevision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),\nunits BIGINT NOT NULL CHECK(units>0),\ndependencies TEXT NOT NULL,\nstate TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','held','released','withdrawn')),\nqueued_at DOUBLE PRECISION NOT NULL,\nexpires_at DOUBLE PRECISION NOT NULL,\ndispatch_sequence BIGINT,\nstop_evidence_ref TEXT,\nenqueue_frontier BIGINT NOT NULL DEFAULT 0 CHECK(enqueue_frontier>=0),\nqueue_sequence BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL UNIQUE,\nUNIQUE(attempt_id,generation),\nCHECK((state='queued' AND dispatch_sequence IS NULL AND stop_evidence_ref IS NULL)\n           OR (state='held' AND dispatch_sequence IS NOT NULL AND stop_evidence_ref IS NULL)\n           OR (state='released' AND dispatch_sequence IS NOT NULL AND stop_evidence_ref IS NOT NULL)\n           OR (state='withdrawn' AND dispatch_sequence IS NULL AND stop_evidence_ref IS NULL)))",
    "CREATE TABLE work_snapshot_sources (snapshot_id TEXT NOT NULL,\nrecord_id TEXT NOT NULL,\nrevision BIGINT NOT NULL CHECK(revision>0),\nPRIMARY KEY(snapshot_id,record_id,revision))",
    "CREATE TABLE work_step_contracts (run_id TEXT NOT NULL,\nstep_id TEXT NOT NULL,\ngeneration TEXT NOT NULL CHECK(length(generation)>0),\nattempt_number BIGINT NOT NULL CHECK(attempt_number>0),\ncontract_json TEXT NOT NULL CHECK(\n            (contract_json IS JSON) AND (CASE WHEN contract_json IS JSON THEN json_typeof(contract_json::json)='object' ELSE FALSE END)\n            AND (CASE WHEN contract_json IS JSON THEN CASE WHEN json_typeof(json_extract_path(contract_json::json,'schema_version'))='number' AND json_extract_path_text(contract_json::json,'schema_version') ~ '^-?[0-9]+$' THEN json_extract_path_text(contract_json::json,'schema_version')::numeric=1 ELSE FALSE END ELSE FALSE END)\n            AND length(contract_json)<=65536),\ncreated_at TEXT NOT NULL,\nPRIMARY KEY(run_id,step_id,generation,attempt_number))",
    "CREATE TABLE work_task_received_receipts (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nwork_item_id TEXT NOT NULL,\njob_id TEXT NOT NULL,\nattempt_revision BIGINT NOT NULL CHECK(attempt_revision>0),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_kind TEXT NOT NULL\n            CHECK(receiver_authorization_kind='receiver'),\nreceiver_authorization_revision BIGINT NOT NULL\n            CHECK(receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL CHECK(receiver_grant_revision>0),\ndelivery_id TEXT NOT NULL CHECK(length(delivery_id) BETWEEN 1 AND 128\n            AND delivery_id !~ '[^A-Za-z0-9._:-]'),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\nnonce TEXT NOT NULL CHECK(length(nonce) BETWEEN 1 AND 128\n            AND nonce !~ '[^A-Za-z0-9._:-]'),\nreceipt_hash TEXT NOT NULL CHECK(length(receipt_hash)=64\n            AND receipt_hash !~ '[^0-9a-f]'),\nreceived_at DOUBLE PRECISION NOT NULL,\nPRIMARY KEY(attempt_id,generation),\nUNIQUE(nonce),\nUNIQUE(delivery_id))",
    "CREATE TABLE work_task_receiver_acceptances (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(TRUE AND generation>0),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_origin_kind TEXT NOT NULL DEFAULT 'receiver'\n            CHECK(receiver_origin_kind='receiver'),\nreceiver_subject_revision BIGINT NOT NULL\n            CHECK(TRUE AND receiver_subject_revision>0),\nreceiver_authorization_revision BIGINT NOT NULL\n            CHECK(TRUE AND receiver_authorization_revision>0),\ndelivery_id TEXT NOT NULL CHECK(length(delivery_id) BETWEEN 1 AND 512),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\nacceptance_sha256 TEXT NOT NULL CHECK(length(acceptance_sha256)=64\n            AND acceptance_sha256 !~ '[^0-9a-f]'),\naccepted_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND accepted_at>0),\nschema_version BIGINT NOT NULL DEFAULT 1\n            CHECK(TRUE AND schema_version=1),\nPRIMARY KEY(attempt_id,generation))",
    "CREATE TABLE work_task_receiver_credentials (attempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(TRUE AND generation>0),\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL\n            CHECK(TRUE AND receiver_subject_revision>0),\nreceiver_authorization_revision BIGINT NOT NULL\n            CHECK(TRUE AND receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL\n            CHECK(TRUE AND receiver_grant_revision>0),\ninstallation_uuid TEXT NOT NULL CHECK(length(installation_uuid)=32\n            AND installation_uuid !~ '[^0-9a-f]'),\nattempt_revision BIGINT NOT NULL CHECK(TRUE AND attempt_revision>0),\nlease_expires_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND lease_expires_at>0),\nexpires_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND expires_at>0),\ndelivery_id TEXT NOT NULL CHECK(length(delivery_id) BETWEEN 1 AND 512),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\ncredential_sha256 TEXT NOT NULL UNIQUE CHECK(length(credential_sha256)=64\n            AND credential_sha256 !~ '[^0-9a-f]'),\nissued_at DOUBLE PRECISION NOT NULL CHECK(TRUE AND issued_at>0),\nschema_version BIGINT NOT NULL DEFAULT 1 CHECK(TRUE AND schema_version=1),\nPRIMARY KEY(attempt_id,generation),\nCHECK(expires_at<=lease_expires_at))",
    "CREATE TABLE work_transition_receipts (event_id TEXT PRIMARY KEY,\nrequest_hash TEXT NOT NULL,\nwork_item_id TEXT NOT NULL)",
    "CREATE TABLE work_workflow_run_capabilities (run_id TEXT NOT NULL,\nrevision BIGINT NOT NULL CHECK(revision>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nprincipal_id TEXT NOT NULL,\nworkflow_id TEXT NOT NULL CHECK(length(workflow_id) BETWEEN 1 AND 128\n            AND workflow_id !~ '[^A-Za-z0-9._:-]'),\ntier TEXT NOT NULL CHECK(tier IN ('script','yaml')),\nrun_generation BIGINT NOT NULL CHECK(run_generation>0),\nspec_hash TEXT NOT NULL CHECK(length(spec_hash)=64\n            AND spec_hash !~ '[^0-9a-f]'),\ncredential_sha256 TEXT NOT NULL CHECK(length(credential_sha256)=64\n            AND credential_sha256 !~ '[^0-9a-f]'),\nstate TEXT NOT NULL CHECK(state IN ('active','revoked')),\nissued_at DOUBLE PRECISION NOT NULL CHECK(issued_at>0),\nexpires_at DOUBLE PRECISION NOT NULL CHECK(expires_at>issued_at),\nPRIMARY KEY(run_id,revision),\nUNIQUE(credential_sha256))",
    "CREATE TABLE work_workflow_step_bindings (binding_id TEXT PRIMARY KEY CHECK(length(binding_id) BETWEEN 1 AND 128\n            AND binding_id !~ '[^A-Za-z0-9._:-]'),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\ntier TEXT NOT NULL CHECK(tier IN ('yaml','script')),\nrun_id TEXT NOT NULL,\nrun_generation BIGINT NOT NULL CHECK(run_generation>0),\nbinding_fingerprint TEXT NOT NULL CHECK(length(binding_fingerprint)=64\n            AND binding_fingerprint !~ '[^0-9a-f]'),\nworkflow_id TEXT NOT NULL CHECK(length(workflow_id) BETWEEN 1 AND 128\n            AND workflow_id !~ '[^A-Za-z0-9._:-]'),\nspec_hash TEXT NOT NULL CHECK(length(spec_hash)=64\n            AND spec_hash !~ '[^0-9a-f]'),\nstep_id TEXT NOT NULL CHECK(length(step_id) BETWEEN 1 AND 128\n            AND step_id !~ '[^A-Za-z0-9._:-]'),\nworkflow_step_attempt BIGINT NOT NULL CHECK(workflow_step_attempt>0),\nprincipal_id TEXT NOT NULL,\nprovision_id TEXT NOT NULL,\nprovision_revision BIGINT NOT NULL CHECK(provision_revision>0),\nprovision_fingerprint TEXT NOT NULL CHECK(length(provision_fingerprint)=64\n            AND provision_fingerprint !~ '[^0-9a-f]'),\nworkflow_subject_id TEXT NOT NULL,\nworkflow_subject_revision BIGINT NOT NULL CHECK(workflow_subject_revision>0),\nworkflow_authorization_kind TEXT NOT NULL CHECK(workflow_authorization_kind='workflow'),\nworkflow_authorization_revision BIGINT NOT NULL CHECK(workflow_authorization_revision>0),\njob_id TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL CHECK(grant_revision>0),\ncontract_id TEXT NOT NULL,\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64\n            AND contract_hash !~ '[^0-9a-f]'),\nsnapshot_id TEXT NOT NULL,\nsnapshot_hash TEXT NOT NULL CHECK(length(snapshot_hash)=64\n            AND snapshot_hash !~ '[^0-9a-f]'),\ndelivery_id TEXT NOT NULL CHECK(length(delivery_id) BETWEEN 1 AND 128\n            AND delivery_id !~ '[^A-Za-z0-9._:-]'),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\nwork_item_id TEXT NOT NULL,\nwork_attempt_id TEXT NOT NULL,\nwork_generation BIGINT NOT NULL CHECK(work_generation>0),\nrequest_hash TEXT NOT NULL CHECK(length(request_hash)=64\n            AND request_hash !~ '[^0-9a-f]'),\nidempotency_key TEXT NOT NULL,\noutput_schema_json TEXT CHECK(output_schema_json IS NULL OR\n            ((output_schema_json IS JSON) AND (CASE WHEN output_schema_json IS JSON THEN json_typeof(output_schema_json::json)='object' ELSE FALSE END)\n             AND length(output_schema_json)<=32768)),\noutput_schema_hash TEXT CHECK(output_schema_hash IS NULL OR\n            (length(output_schema_hash)=64 AND output_schema_hash !~ '[^0-9a-f]')),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_kind TEXT NOT NULL CHECK(receiver_authorization_kind='receiver'),\nreceiver_authorization_revision BIGINT NOT NULL CHECK(receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL CHECK(receiver_grant_revision>0),\nreceiver_received_action TEXT NOT NULL CHECK(receiver_received_action='task_received'),\nreceiver_result_action TEXT NOT NULL CHECK(receiver_result_action='task_result'),\ncreated_at DOUBLE PRECISION NOT NULL CHECK(created_at>0),\nUNIQUE(tier,run_id,run_generation,step_id,workflow_step_attempt),\nUNIQUE(work_attempt_id,work_generation),\nUNIQUE(binding_id,work_attempt_id,work_generation,work_item_id),\nUNIQUE(binding_id,work_attempt_id,work_generation),\nUNIQUE(principal_id,workflow_id,step_id,idempotency_key),\nCHECK((output_schema_json IS NULL)=(output_schema_hash IS NULL)))",
    "CREATE TABLE work_workflow_step_projections (binding_id TEXT PRIMARY KEY,\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\naccepted_result_id TEXT NOT NULL,\ncontent_hash TEXT NOT NULL CHECK(length(content_hash)=64\n            AND content_hash !~ '[^0-9a-f]'),\nprojected_at DOUBLE PRECISION NOT NULL CHECK(projected_at>0))",
    "CREATE TABLE work_workflow_step_provisions (principal_id TEXT NOT NULL,\nworkflow_id TEXT NOT NULL CHECK(length(workflow_id) BETWEEN 1 AND 128\n            AND workflow_id !~ '[^A-Za-z0-9._:-]'),\nstep_id TEXT NOT NULL CHECK(length(step_id) BETWEEN 1 AND 128\n            AND step_id !~ '[^A-Za-z0-9._:-]'),\nrevision BIGINT NOT NULL CHECK(revision>0),\nid TEXT NOT NULL CHECK(length(id) BETWEEN 1 AND 128\n            AND id !~ '[^A-Za-z0-9._:-]'),\nprovision_fingerprint TEXT NOT NULL CHECK(length(provision_fingerprint)=64\n            AND provision_fingerprint !~ '[^0-9a-f]'),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nstate TEXT NOT NULL CHECK(state IN ('active','retired')),\nissuer_id TEXT NOT NULL,\nspec_hash TEXT NOT NULL CHECK(length(spec_hash)=64\n            AND spec_hash !~ '[^0-9a-f]'),\nworkflow_subject_id TEXT NOT NULL,\nworkflow_subject_revision BIGINT NOT NULL CHECK(workflow_subject_revision>0),\nworkflow_authorization_kind TEXT NOT NULL CHECK(workflow_authorization_kind='workflow'),\nworkflow_authorization_revision BIGINT NOT NULL CHECK(workflow_authorization_revision>0),\njob_id TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL CHECK(grant_revision>0),\ncontract_id TEXT NOT NULL CHECK(length(contract_id) BETWEEN 1 AND 128),\ncontract_json TEXT NOT NULL CHECK((contract_json IS JSON)\n            AND (CASE WHEN contract_json IS JSON THEN json_typeof(contract_json::json)='object' ELSE FALSE END) AND length(contract_json)<=32768),\ncontract_hash TEXT NOT NULL CHECK(length(contract_hash)=64\n            AND contract_hash !~ '[^0-9a-f]'),\nsnapshot_id TEXT NOT NULL,\nsnapshot_hash TEXT NOT NULL CHECK(length(snapshot_hash)=64\n            AND snapshot_hash !~ '[^0-9a-f]'),\ndelivery_json TEXT NOT NULL CHECK((delivery_json IS JSON)\n            AND (CASE WHEN delivery_json IS JSON THEN json_typeof(delivery_json::json)='object' ELSE FALSE END) AND length(delivery_json)<=65536),\ndelivery_template_hash TEXT NOT NULL CHECK(length(delivery_template_hash)=64\n            AND delivery_template_hash !~ '[^0-9a-f]'),\nadapter_version BIGINT NOT NULL CHECK(adapter_version>0),\nlease_seconds BIGINT NOT NULL CHECK(lease_seconds BETWEEN 1 AND 3600),\noutput_schema_json TEXT CHECK(output_schema_json IS NULL OR\n            ((output_schema_json IS JSON) AND (CASE WHEN output_schema_json IS JSON THEN json_typeof(output_schema_json::json)='object' ELSE FALSE END)\n             AND length(output_schema_json)<=32768)),\noutput_schema_hash TEXT CHECK(output_schema_hash IS NULL OR\n            (length(output_schema_hash)=64 AND output_schema_hash !~ '[^0-9a-f]')),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_kind TEXT NOT NULL CHECK(receiver_authorization_kind='receiver'),\nreceiver_authorization_revision BIGINT NOT NULL CHECK(receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL CHECK(receiver_grant_revision>0),\nreceiver_received_action TEXT NOT NULL CHECK(receiver_received_action='task_received'),\nreceiver_result_action TEXT NOT NULL CHECK(receiver_result_action='task_result'),\ncreated_at DOUBLE PRECISION NOT NULL CHECK(created_at>0),\nPRIMARY KEY(principal_id,workflow_id,step_id,revision),\nUNIQUE(principal_id,workflow_id,step_id,revision,id),\nCHECK((output_schema_json IS NULL)=(output_schema_hash IS NULL)))",
    "CREATE TABLE work_workflow_step_receiver_acceptances (binding_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_kind TEXT NOT NULL CHECK(receiver_authorization_kind='receiver'),\nreceiver_authorization_revision BIGINT NOT NULL CHECK(receiver_authorization_revision>0),\ndelivery_id TEXT NOT NULL,\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\nacceptance_sha256 TEXT NOT NULL CHECK(length(acceptance_sha256)=64\n            AND acceptance_sha256 !~ '[^0-9a-f]'),\naccepted_at DOUBLE PRECISION NOT NULL CHECK(accepted_at>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nPRIMARY KEY(attempt_id,generation))",
    "CREATE TABLE work_workflow_step_receiver_credentials (binding_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_revision BIGINT NOT NULL CHECK(receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL CHECK(receiver_grant_revision>0),\ninstallation_uuid TEXT NOT NULL CHECK(length(installation_uuid)=32\n            AND installation_uuid !~ '[^0-9a-f]'),\nattempt_revision BIGINT NOT NULL CHECK(attempt_revision>0),\nlease_expires_at DOUBLE PRECISION NOT NULL CHECK(lease_expires_at>0),\nexpires_at DOUBLE PRECISION NOT NULL CHECK(expires_at>0 AND expires_at<=lease_expires_at),\ndelivery_id TEXT NOT NULL,\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\ncredential_sha256 TEXT NOT NULL UNIQUE CHECK(length(credential_sha256)=64\n            AND credential_sha256 !~ '[^0-9a-f]'),\nissued_at DOUBLE PRECISION NOT NULL CHECK(issued_at>0),\nPRIMARY KEY(attempt_id,generation))",
    "CREATE TABLE work_workflow_step_retry_authorizations (authorization_id TEXT PRIMARY KEY CHECK(length(authorization_id) BETWEEN 1 AND 128\n            AND authorization_id !~ '[^A-Za-z0-9._:-]'),\nauthorization_fingerprint TEXT NOT NULL CHECK(length(authorization_fingerprint)=64\n            AND authorization_fingerprint !~ '[^0-9a-f]'),\nbinding_id TEXT NOT NULL UNIQUE,\nbinding_fingerprint TEXT NOT NULL CHECK(length(binding_fingerprint)=64\n            AND binding_fingerprint !~ '[^0-9a-f]'),\ntier TEXT NOT NULL CHECK(tier IN ('yaml','script')),\nrun_id TEXT NOT NULL,\nrun_generation BIGINT NOT NULL CHECK(run_generation>0),\nworkflow_id TEXT NOT NULL,\nspec_hash TEXT NOT NULL CHECK(length(spec_hash)=64\n            AND spec_hash !~ '[^0-9a-f]'),\nstep_id TEXT NOT NULL,\nworkflow_step_attempt BIGINT NOT NULL CHECK(workflow_step_attempt>0),\nprincipal_id TEXT NOT NULL,\nprovision_id TEXT NOT NULL,\nprovision_revision BIGINT NOT NULL CHECK(provision_revision>0),\nprovision_fingerprint TEXT NOT NULL CHECK(length(provision_fingerprint)=64\n            AND provision_fingerprint !~ '[^0-9a-f]'),\nwork_item_id TEXT NOT NULL,\nwork_attempt_id TEXT NOT NULL,\nwork_generation BIGINT NOT NULL CHECK(work_generation>0),\nauthorized_at DOUBLE PRECISION NOT NULL CHECK(authorized_at>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nUNIQUE(work_attempt_id,work_generation))",
    "CREATE TABLE work_workflow_step_task_received_receipts (binding_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nschema_version BIGINT NOT NULL CHECK(schema_version=1),\nwork_item_id TEXT NOT NULL,\njob_id TEXT NOT NULL,\nattempt_revision BIGINT NOT NULL CHECK(attempt_revision>0),\nreceiver_subject_id TEXT NOT NULL,\nreceiver_subject_revision BIGINT NOT NULL CHECK(receiver_subject_revision>0),\nreceiver_authorization_kind TEXT NOT NULL CHECK(receiver_authorization_kind='receiver'),\nreceiver_authorization_revision BIGINT NOT NULL CHECK(receiver_authorization_revision>0),\nreceiver_grant_id TEXT NOT NULL,\nreceiver_grant_revision BIGINT NOT NULL CHECK(receiver_grant_revision>0),\ndelivery_id TEXT NOT NULL CHECK(length(delivery_id) BETWEEN 1 AND 128\n            AND delivery_id !~ '[^A-Za-z0-9._:-]'),\ndelivery_hash TEXT NOT NULL CHECK(length(delivery_hash)=64\n            AND delivery_hash !~ '[^0-9a-f]'),\nnonce TEXT NOT NULL CHECK(length(nonce) BETWEEN 1 AND 128\n            AND nonce !~ '[^A-Za-z0-9._:-]'),\nreceipt_hash TEXT NOT NULL CHECK(length(receipt_hash)=64\n            AND receipt_hash !~ '[^0-9a-f]'),\nreceived_at DOUBLE PRECISION NOT NULL CHECK(received_at>0),\nPRIMARY KEY(attempt_id,generation),\nUNIQUE(nonce),\nUNIQUE(delivery_id))",
    "CREATE TABLE work_worktree_evidence (id TEXT PRIMARY KEY,\njob_id TEXT NOT NULL,\nwork_item_id TEXT NOT NULL,\nattempt_id TEXT NOT NULL,\ngeneration BIGINT NOT NULL CHECK(generation>0),\nattempt_revision BIGINT NOT NULL CHECK(attempt_revision>0),\ncontent_hash TEXT NOT NULL CHECK(length(content_hash)=64),\nimmutable_location TEXT NOT NULL CHECK(immutable_location=content_hash),\nbyte_length BIGINT NOT NULL CHECK(byte_length>=0),\nbase_head TEXT NOT NULL,\nstop_evidence_ref TEXT NOT NULL,\ngrant_id TEXT NOT NULL,\ngrant_revision BIGINT NOT NULL,\ncreated_at DOUBLE PRECISION NOT NULL,\nUNIQUE(attempt_id,content_hash))",
    "CREATE TABLE work_store_control (singleton INTEGER PRIMARY KEY CHECK(singleton=1), store_identity TEXT NOT NULL UNIQUE, store_uuid TEXT NOT NULL UNIQUE, revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0), created_at DOUBLE PRECISION NOT NULL)",
    """CREATE FUNCTION work_store_control_identity_immutable_fn() RETURNS trigger
       LANGUAGE plpgsql AS $$
       BEGIN
           IF OLD.singleton IS DISTINCT FROM NEW.singleton
              OR OLD.store_identity IS DISTINCT FROM NEW.store_identity
              OR OLD.store_uuid IS DISTINCT FROM NEW.store_uuid
              OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
               RAISE EXCEPTION 'Work store identity is immutable';
           END IF;
           RETURN NEW;
       END
       $$""",
    """CREATE TRIGGER work_store_control_identity_immutable
       BEFORE UPDATE ON work_store_control
       FOR EACH ROW EXECUTE FUNCTION work_store_control_identity_immutable_fn()""",
    """CREATE FUNCTION work_store_control_no_delete_fn() RETURNS trigger
       LANGUAGE plpgsql AS $$
       BEGIN
           RAISE EXCEPTION 'Work store identity cannot be deleted';
       END
       $$""",
    """CREATE TRIGGER work_store_control_no_delete
       BEFORE DELETE ON work_store_control
       FOR EACH ROW EXECUTE FUNCTION work_store_control_no_delete_fn()""",
